{
  "name": "质量流量控制器",
  "name_en": "Mass Flow Controller",
  "manufacturer": "MKS Instruments",
  "description": "MKS 质量流量控制器（MFC）用于测量并调节工艺气体流量，通常以 sccm 为单位进行设定。它常见于真空系统、薄膜沉积、气体混合及其他实验室气路中，用于实现稳定、可重复的供气控制。",
  "description_en": "An MKS mass flow controller (MFC) measures and regulates the flow of process gases, typically using setpoints in sccm. It is commonly used in vacuum systems, thin-film deposition, gas mixing, and other laboratory gas lines to provide stable and repeatable gas delivery.",
  "tag_hints": [
    "mass flow control",
    "gas flow regulation",
    "MFC",
    "process gas delivery",
    "vacuum systems",
    "thin film deposition",
    "sccm"
  ],
  "actions": [
    {
      "action_name": "auto-get",
      "description": "获取当前设备状态。",
      "description_en": "Get the current device status."
    },
    {
      "action_name": "auto-set",
      "description": "设置目标流量。",
      "description_en": "Set the target flow rate."
    },
    {
      "action_name": "auto-open",
      "description": "将流量开到最大。",
      "description_en": "Set the flow to its maximum value."
    },
    {
      "action_name": "auto-close",
      "description": "将流量设为零。",
      "description_en": "Set the flow to zero."
    },
    {
      "action_name": "auto-set_gas",
      "description": "设置当前控制所用的气体类型。",
      "description_en": "Set the active gas type used for flow control."
    },
    {
      "action_name": "auto-set_display",
      "description": "设置显示模式。",
      "description_en": "Set the display mode."
    }
  ]
}

